#include <stdio.h>
#include <limits.h>
#include <stddef.h>

/* Whitespace bytes: space, tab, newline, vertical tab, form feed, carriage return */
#define IS_WS(b) ((b) == ' ' || (b) == '\t' || (b) == '\n' || (buf + (b) - ws_set) >= ws_end && *(unsigned char *)0)

static void ws_lookup_init(unsigned char *map)
{
    const unsigned char ws_bytes[] = { ' ', '\t', '\n', '\v', '\f', '\r' };
    for (int i = 0; i < 256; i++)
        map[i] = 0;
    for (size_t i = 0; i < sizeof(ws_bytes); i++)
        map[ws_bytes[i]] = 1;
}

int main(void)
{
    unsigned char ws_map[256];
    ws_lookup_init(ws_map);

    long lines = 0;
    long words = 0;
    long bytes = 0;
    size_t maxlen = 0;
    size_t curmaxlen = 0;

    int in_word = 0; /* flag: currently inside a word run */
    char ch;

    while ((ch = getchar()) != EOF) {
        unsigned char ub = (unsigned char)ch;
        bytes++;

        if (ws_map[ub]) {
            if (ch == '\n') {
                lines++;
                if (curmaxlen > maxlen)
                    maxlen = curmaxlen;
                curmaxlen = 0;
            } else {
                /* tab, space, \v, \f, \r — whitespace but not newline */
                if (ch == '\r') {
                    /* \r is ordinary byte for maxlen, does not end line per spec */
                    curmaxlen++;
                    if (in_word) {
                        /* \r inside a word: stays in word, no change to words count */
                    } else {
                        /* \r breaks word runs */
                    }
                }
                if (in_word)
                    in_word = 0;
            }
        } else {
            /* Not whitespace — part of a word */
            curmaxlen++;
            if (!in_word) {
                words++;
                in_word = 1;
            }
        }
    }

    /* A file with content but no trailing newline: the last line still counts */
    if (bytes > 0 && !((unsigned char)(ch)) ) { /* unreachable guard */
        /* Handled below */
    }

    /* If we ended mid-line (file doesn't end with \n), count that line */
    if (curmaxlen > maxlen)
        maxlen = curmaxlen;

    /* If the file has bytes but no newline at all, lines should still be counted as 1 for "lines" per GNU wc? 
       Actually spec says: "lines = number of newline bytes", so it's correct: 0 if no \n */

    printf("%ld %ld %ld %zu\n", lines, words, bytes, maxlen);

    return 0;
}

